-- Expanded Holistic House engaging battery v2 batch 2.
begin;
do $$
declare
  cfg jsonb;
  locale text;
  questions jsonb;
  item_ids jsonb;
  dimension_class text;
  direction text;
  timeframe text;
  definition jsonb;
  test_id uuid;
  v_content_hash text;
begin
  for cfg in select value from jsonb_array_elements($configs$[{"key":"hh-change-readiness","titles":{"en":"Ready for Change?","ru":"Готовность к переменам"},"axis":"resources","topics":["motivation","function","resources"],"categoryAffinities":["other","work-money","emotions"],"testLength":"medium","en":["I can name what I want to change.","The cost of staying the same is becoming clear to me.","I see at least one realistic first step.","I am willing to tolerate some discomfort while changing.","I have enough support or structure to begin.","I am ready to experiment rather than wait for certainty."],"ru":["Я могу назвать, что именно хочу изменить.","Цена сохранения всего как есть становится для меня понятнее.","Я вижу хотя бы один реалистичный первый шаг.","Я готов выдержать некоторое неудобство в процессе изменений.","У меня достаточно поддержки или структуры, чтобы начать.","Я готов экспериментировать, а не ждать полной уверенности."],"ids":{"en":"19ea3e6d-147d-5513-a9e7-eb51cab26be0","ru":"fc6a332c-86e3-51b7-9899-1659ffa9b6c5"},"hashes":{"en":"sha256:f37f0dc1f9f9b58613134b7c6a9088477a1b4ef8ef9dd4c9c2353eae402fb122","ru":"sha256:a2277cafb02b45b52c05ef5dbfedc7ce941a7d21e8ce0f84de4050b64b4add4f"},"negative":false},{"key":"hh-workload-weather","titles":{"en":"Workload Weather","ru":"Погода нагрузки"},"axis":"function","topics":["stress","work","function"],"categoryAffinities":["work-money","energy"],"testLength":"medium","en":["My current workload feels manageable.","I know which tasks can wait.","I have enough uninterrupted time for important work.","My responsibilities fit the energy I actually have.","I can say no or renegotiate when the load is too high.","At the end of the day, work does not completely consume the rest of my life."],"ru":["Моя текущая нагрузка ощущается управляемой.","Я понимаю, какие задачи могут подождать.","У меня есть достаточно непрерывного времени для важной работы.","Мои обязанности соответствуют энергии, которая у меня реально есть.","Я могу сказать «нет» или пересогласовать, когда нагрузки слишком много.","В конце дня работа не поглощает полностью остальную жизнь."],"ids":{"en":"460da1b1-e0c9-5dc2-9598-ff609974e9c9","ru":"1f1142d4-34e0-5d21-a480-44d2aff92746"},"hashes":{"en":"sha256:fc097227dfbbaa0d7ca97bd1f1373fa63b37ac26d0d2f537aec56c0ef73836a9","ru":"sha256:a1145393796b2ffb80744848289a21064819a65b9e99e97ed95e5e21b531ca99"},"negative":false},{"key":"hh-body-signals","titles":{"en":"Body Signals","ru":"Сигналы тела"},"axis":"state","topics":["body","stress","energy"],"categoryAffinities":["body","energy"],"testLength":"short","en":["I notice tension in my body before it becomes overwhelming.","I can tell when I need food, water, movement or rest.","I notice changes in my breathing when I am stressed.","I can identify where I hold tension.","My body gives me useful information about overload.","I can respond to a body signal instead of always ignoring it."],"ru":["Я замечаю напряжение в теле до того, как оно становится слишком сильным.","Я понимаю, когда мне нужны еда, вода, движение или отдых.","Я замечаю изменения дыхания при стрессе.","Я могу определить, где удерживаю напряжение.","Тело даёт мне полезную информацию о перегрузке.","Я могу откликнуться на сигнал тела, а не всегда игнорировать его."],"ids":{"en":"bad7545e-0152-560d-8c2b-fe633995421e","ru":"9d5ee46e-35c7-5585-8db0-942db578cf44"},"hashes":{"en":"sha256:67a0be7b84107ac5e41d9d0fc9a9a6182cc774dde6595e166fec8138e928cb2f","ru":"sha256:5f6c12d5e6198e9bcd1488af62a0bb432674843ade9dd502378da982205ea066"},"negative":false},{"key":"hh-rest-permission","titles":{"en":"Can You Rest?","ru":"Можно ли тебе отдыхать?"},"axis":"resources","topics":["recovery","self-support","stress"],"categoryAffinities":["energy","emotions","other"],"testLength":"short","en":["I can rest before I am completely exhausted.","I can take a break without needing to earn it first.","Rest does not automatically make me feel guilty.","I can stop when something is good enough.","I can have unproductive time without feeling that I am failing.","I can return to activity with more energy after a real pause."],"ru":["Я могу отдыхать до того, как полностью истощусь.","Я могу сделать паузу, не заслуживая её заранее.","Отдых не вызывает у меня автоматически чувство вины.","Я могу остановиться, когда сделано достаточно хорошо.","Я могу иметь непродуктивное время без ощущения, что проваливаюсь.","После настоящей паузы я могу вернуться к делам с большей энергией."],"ids":{"en":"33f94ea2-9865-5929-820f-8565f01948f9","ru":"518cb960-5abb-5921-bba0-c1a3c5bf85ec"},"hashes":{"en":"sha256:4de1146596ca14226ff739fed116df06d40077e5ad0077fc20bef701b85dc1a5","ru":"sha256:f9accc64735577903cb8a271be3c17041fe4a5d8be9170a77a0a2dba536010b2"},"negative":false},{"key":"hh-closeness-compass","titles":{"en":"Closeness Compass","ru":"Компас близости"},"axis":"resources","topics":["relationships","support","self-support"],"categoryAffinities":["relationships","emotions"],"testLength":"medium","en":["I can notice when I want closeness.","I can notice when I need more space.","I can ask for reassurance without demanding certainty.","I can stay connected while keeping my own preferences.","I can receive care without immediately needing to repay it.","I can tolerate a little distance without assuming the relationship is lost."],"ru":["Я замечаю, когда мне хочется близости.","Я замечаю, когда мне нужно больше пространства.","Я могу попросить подтверждения или поддержки, не требуя полной гарантии.","Я могу оставаться в контакте, сохраняя собственные предпочтения.","Я могу принимать заботу, не чувствуя, что должен немедленно отплатить.","Я могу выдержать небольшую дистанцию, не решая сразу, что отношения потеряны."],"ids":{"en":"235b5c19-f0c9-598e-aee7-6663b4167700","ru":"ddc29eaa-d4de-50d4-879f-a84ad94be944"},"hashes":{"en":"sha256:b4300ea711448ac2aff87460f8265547f63cab62c8723c4be56383595095e51b","ru":"sha256:092daf4a9916b1654419c7129443fe73b8772c6ec3026ef433f0085ac573ecfc"},"negative":false},{"key":"hh-confidence-pulse","titles":{"en":"Confidence Pulse","ru":"Пульс уверенности"},"axis":"resources","topics":["resources","function","mood"],"categoryAffinities":["emotions","work-money","other"],"testLength":"short","en":["I trust myself to handle ordinary problems.","I can make a decision without needing everyone to approve.","I can recover after making a mistake.","I can speak up when something matters to me.","I can try something before knowing I will succeed.","I can recognize skills I already have."],"ru":["Я доверяю себе в решении обычных проблем.","Я могу принять решение без необходимости получить одобрение всех.","Я могу восстановиться после ошибки.","Я могу высказаться, когда для меня что-то важно.","Я могу попробовать что-то, не зная заранее, что получится.","Я могу признать навыки, которые у меня уже есть."],"ids":{"en":"c3c768fc-00b2-58d1-9f02-1fba03c8b2ff","ru":"74023a68-d475-5b72-92cd-20bccff1629c"},"hashes":{"en":"sha256:ceba332c736059cf7e3faa47418f835b388aaf6f55abebf962a470ba89cb900c","ru":"sha256:d0d3527bd821103da69431191b8c5e0c6d7aa75d15840d932652ba6ff2ca402a"},"negative":false},{"key":"hh-playfulness-pulse","titles":{"en":"Playfulness Pulse","ru":"Пульс игры"},"axis":"resources","topics":["recovery","mood","energy"],"categoryAffinities":["energy","emotions","other"],"testLength":"short","en":["I can do something just because it is enjoyable.","I have moments of curiosity without a practical goal.","Humour is available to me sometimes.","I can improvise when plans change.","I notice things that feel interesting or alive.","I can allow a little silliness without judging myself."],"ru":["Я могу делать что-то просто потому, что это приятно.","У меня бывают моменты любопытства без практической цели.","Иногда мне доступен юмор.","Я могу импровизировать, когда планы меняются.","Я замечаю то, что кажется интересным или живым.","Я могу позволить себе немного несерьёзности без самоосуждения."],"ids":{"en":"d0ec4ef1-2533-5c11-bea6-ae97cea33ca4","ru":"b1137f82-a2a5-5e54-bd0f-7bc140958285"},"hashes":{"en":"sha256:3084c3324390cf9d64ffded9917f0226a5c2ebe3ba0f01de08db96992fedd608","ru":"sha256:2225abe06e4d7edeb2ce9cd09fc3c8bbdf1be0577bfb5d1ca44ffec9ddc2b40b"},"negative":false},{"key":"hh-daily-rhythm","titles":{"en":"Daily Rhythm","ru":"Ритм дня"},"axis":"function","topics":["sleep","energy","function","recovery"],"categoryAffinities":["body","energy","work-money"],"testLength":"medium","en":["My sleep and wake times are reasonably consistent.","I eat and drink at intervals that support my energy.","There is some predictable structure in my day.","I have moments for movement or changing posture.","I have at least one transition between work and rest.","My daily rhythm helps me know what comes next."],"ru":["Время сна и пробуждения у меня достаточно стабильное.","Я ем и пью с интервалами, которые поддерживают энергию.","В моём дне есть некоторая предсказуемая структура.","У меня есть моменты для движения или смены положения тела.","У меня есть хотя бы один переход между работой и отдыхом.","Ритм дня помогает мне понимать, что будет дальше."],"ids":{"en":"70a5cd6d-bfc9-5d8d-902d-5615964534d4","ru":"4179a52b-27bf-567f-96b1-c67da0211131"},"hashes":{"en":"sha256:caa15f54bf26134980bbf322b991fb9841d7ea925764c0d3355840945a2fe788","ru":"sha256:f52be5c38ea7c55525fffab0d08499b018accfc80b2f2dfc955b9e597b552e10"},"negative":false},{"key":"hh-money-pressure","titles":{"en":"Money Pressure","ru":"Давление денег"},"axis":"state","topics":["stress","work","resources"],"categoryAffinities":["work-money","emotions"],"testLength":"medium","en":["Money worries take up a lot of mental space.","Financial uncertainty makes it harder to relax.","I avoid looking at money-related information because it feels stressful.","I can separate immediate financial facts from catastrophic thoughts.","I know one practical financial action I can take.","I have someone or somewhere I can turn to for practical financial information if needed."],"ru":["Денежные тревоги занимают много места в голове.","Финансовая неопределённость мешает мне расслабляться.","Я избегаю смотреть финансовую информацию, потому что это вызывает стресс.","Я могу отделять реальные финансовые факты от катастрофических мыслей.","Я знаю одно практическое финансовое действие, которое могу сделать.","Если нужно, я знаю, к кому или куда обратиться за практической финансовой информацией."],"ids":{"en":"d4cda843-f234-5304-aca0-17dfa59e4c3c","ru":"13782a7c-a7e3-5daa-a6ac-bab2e78f93ef"},"hashes":{"en":"sha256:7991d7d69831c2e8e06724090c463d921f001ac5b2939772501c113972debcec","ru":"sha256:5a91ec5c9faae1e7ffdd27db8c736369d229050f0dfbbe2dbc6897d3eeca7b31"},"negative":true},{"key":"hh-overthinking-loop","titles":{"en":"Overthinking Loop","ru":"Петля переосмысления"},"axis":"state","topics":["anxiety","clarity","stress"],"categoryAffinities":["emotions","energy","other"],"testLength":"short","en":["I replay conversations or decisions long after they are over.","My mind keeps searching for certainty that is not available.","Thinking more often makes me feel less clear rather than more clear.","I return to the same question without finding new information.","It is hard to shift attention away from a worry.","A concrete action or pause can sometimes interrupt the loop."],"ru":["Я долго прокручиваю разговоры или решения после того, как они закончились.","Мой ум продолжает искать уверенность, которой невозможно получить.","Чем больше я думаю, тем меньше ясности, а не больше.","Я возвращаюсь к одному и тому же вопросу без новой информации.","Мне трудно переключить внимание с тревожной темы.","Конкретное действие или пауза иногда помогают прервать петлю."],"ids":{"en":"78e8bbd2-20d3-5013-9590-fc686744b9e8","ru":"14474c94-072c-50a4-b965-e80a3db77455"},"hashes":{"en":"sha256:2f5e5c8e227c58e6229ad6e34caf54e00d797924a37c4fdeaf1307de3a425128","ru":"sha256:b47fcd65ceb8bd585ecfe55ad4656e9558d02cbe4aa0db6824be460d80895211"},"negative":true}]$configs$::jsonb)
  loop
    foreach locale in array array['en','ru']
    loop
      select jsonb_agg(
        jsonb_build_object(
          'id',(cfg->>'key')||'.'||lpad(ord::text,2,'0'),
          'text',txt,
          'required',true,
          'direction',case when (cfg->>'negative')::boolean then 'lower-reported-difficulty' else 'higher-reported-resource' end
        ) order by ord
      ) into questions
      from jsonb_array_elements_text(cfg->locale) with ordinality as q(txt,ord);

      select jsonb_agg((cfg->>'key')||'.'||lpad(ord::text,2,'0') order by ord)
      into item_ids
      from generate_series(1,jsonb_array_length(cfg->locale)) as ord;

      dimension_class := case cfg->>'axis' when 'function' then 'function' when 'state' then 'state' else 'resources' end;
      direction := case when (cfg->>'negative')::boolean then 'lower-reported-difficulty' else 'higher-reported-resource' end;
      timeframe := case when cfg->>'key' in ('hh-sleep-reset','hh-evening-landing','hh-workload-weather','hh-money-pressure','hh-daily-rhythm') then 'past-7-days' else 'right-now' end;
      test_id := (cfg->'ids'->>locale)::uuid;
      v_content_hash := cfg->'hashes'->>locale;

      definition := jsonb_build_object(
        'id',test_id::text,'key',cfg->>'key','version','v1','instrumentLocale',locale,
        'translationVersion','hh-'||locale||'-v1','timeframe',timeframe,
        'scoringKey','configured','scoringVersion','v1','resultVersion','v1',
        'title',cfg->'titles'->>locale,
        'source',jsonb_build_object('title','Holistic House — '||(cfg->'titles'->>'en'),'status','original-playful-non-diagnostic-reflection','reviewedAt','2026-10-06'),
        'answerScale',jsonb_build_object('min',0,'max',4),
        'responseAnchors',case when locale='ru'
          then '["Совсем нет","Немного","Отчасти","В значительной степени","Очень сильно"]'::jsonb
          else '["Not at all","A little","Somewhat","Quite a lot","Very much"]'::jsonb end,
        'scoring',jsonb_build_object('dimensions',jsonb_build_array(jsonb_build_object(
          'key',dimension_class||'.'||replace(regexp_replace(cfg->>'key','^hh-',''),'-','_')||'.overall',
          'method','mean','items',item_ids,'min',0,'max',4,'dimensionClass',dimension_class,
          'sourceConstruct',cfg->'titles'->>locale,'direction',direction
        ))),
        'questions',questions,'optionalContext','[]'::jsonb,
        'suggestedRepeatDays',case when cfg->>'testLength'='short' then 7 else 14 end,
        'contentHash',v_content_hash
      );

      if exists(select 1 from app.assessment_versions where id=test_id and app.assessment_versions.content_hash<>v_content_hash) then
        raise exception 'Published engaging assessment definition % differs from reviewed definition', test_id;
      end if;

      insert into app.assessment_versions(
        id,definition_key,definition_version,instrument_locale,translation_version,
        definition,questions,answer_schema,scoring_key,scoring_version,result_schema,
        timeframe,source_metadata,content_hash
      ) values (
        test_id,definition->>'key','v1',locale,definition->>'translationVersion',
        definition,questions,jsonb_build_object('type','integer','minimum',0,'maximum',4),
        'configured','v1',jsonb_build_object('version','v1'),timeframe,definition->'source',v_content_hash
      ) on conflict(id) do nothing;
    end loop;
  end loop;
end $$;
commit;
